description:
Design a D flip-flop with asynchronous active-low reset functionality. The output Q holds the value of the input D on the rising edge of the clock signal CLK. If the RESET_B input is low, the flip-flop forces the output Q to zero regardless of the clock state, enabling asynchronous reset behavior.
module top_module(
    input D, RESET_B, CLK,
    output reg Q  // Change output to output reg
);

testbench:
`timescale 1ns/1ps

module top_module_tb;

    // Testbench signals (sequential circuit)
    reg CLK;
    reg D;
    reg RESET_B;
    wire Q;

    // Test tracking
    integer test_num;
    integer pass_count;
    integer fail_count;

    // Instantiate the DUT (Device Under Test)
    top_module dut (
        .CLK(CLK),
        .D(D),
        .RESET_B(RESET_B),
        .Q(Q)
    );

    // Clock generation (10ns period)
    initial begin
        CLK = 0;
        forever #5 CLK = ~CLK;
    end

        task reset_dut;

        begin
            RESET_B = 0;
            D = 0;
            #(15);
            RESET_B = 1;
            #(5);
        end
        endtask
    task testcase001;

        begin
            test_num = 1;
            reset_dut();

            RESET_B = 0;
            #2;
            #1;

            check_outputs(1'b0);
        end
        endtask

    task testcase002;

        begin
            test_num = 2;
            reset_dut();
            @(negedge CLK);
            D = 1;
            @(posedge CLK);
            #2;
            #1;

            check_outputs(1'b1);
