module counter12bit_up (
    input clk,
    input rst,
    input en,
    output [11:0] q
);

    reg [11:0] q_reg;

    always @(posedge clk or posedge rst) begin
        if (rst)
            q_reg <= 12'b000000000000;
        else if (en)
            q_reg <= q_reg + 1;
    end

    assign q = q_reg;

endmodule

