        .clk(clk),
        .data_in(data_in),
        .shift_load(shift_load),
        .data_out(data_out)
    );

    // Clock generation (10ns period)
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

        task reset_dut;

    begin
        data_in = 4'b0000;
        shift_load = 1'b1;
        @(posedge clk);
        #1;
    end
