module top_module(q, qbar, clock, data, PREbar, CLRbar, Wen);input  clock;
    input  [31:0] data;
    input  PREbar;
    input  CLRbar;
    output Wen;
    output [31:0] q, qbar;
    reg    [31:0] q;
    reg    Wen;

